def build_group_cards(group_probas):
    groups_html = ""
    for idx, (g, teams) in enumerate(GROUPS.items()):
        color = GROUP_COLORS[idx % len(GROUP_COLORS)]
        team_data = []
        for team in teams:
            gp = group_probas.get(f"{g}_{team}", {})
            team_data.append((team, gp.get("proba_1st", 0), gp.get("proba_2nd", 0), gp.get("proba_qualified", 0)))
        team_data.sort(key=lambda x: x[1], reverse=True)
        rows = ""
        for team, p1, p2, qual in team_data:
            if qual >= 60:
                dot_color = "#009B4E"; qual_color = "#009B4E"
            elif qual >= 35:
                dot_color = "#CC8800"; qual_color = "#CC8800"
            else:
                dot_color = "#aaa"; qual_color = "var(--text-muted)"
            name_weight = "500" if qual >= 50 else "400"
            name_color = "var(--text-primary)" if qual >= 50 else "var(--text-secondary)"
            rows += (
                '<div class="grp-row">'
                f'<div class="grp-team"><span class="dot" style="background:{dot_color};"></span>'
                f'<span style="font-weight:{name_weight};color:{name_color};">{team}</span></div>'
                f'<span class="grp-val">{p1:.0f}%</span>'
                f'<span class="grp-val muted">{p2:.0f}%</span>'
                f'<span class="grp-val" style="font-weight:500;color:{qual_color};">{qual:.0f}%</span>'
                '</div>'
            )
        groups_html += (
            '<div class="group-card">'
            f'<div class="group-card-header" style="background:{color};">'
            f'<span class="group-name">Group {g}</span>'
            f'<span class="group-teams">{" &middot; ".join(teams)}</span>'
            '</div>'
            '<div class="group-card-body">'
            '<div class="grp-row grp-row-head"><span>Team</span>'
            '<span class="grp-val">1st</span><span class="grp-val">2nd</span><span class="grp-val">Qual.</span></div>'
            f'{rows}'
            '</div></div>'
        )
    return groups_html


def build_proba_rows(probas_by_team):
    top_teams = sorted(probas_by_team.values(), key=lambda x: x.get("proba_champion", 0), reverse=True)[:15]
    rows = ""
    for t in top_teams:
        team = t["team"]
        pc = t.get("proba_champion", 0); pf = t.get("proba_finalist", 0)
        p3 = t.get("proba_third", 0);    p4 = t.get("proba_fourth", 0)
        ps = t.get("proba_semis", 0);    rank = FIFA_RANKING.get(team, 99)
        bar = min(pc * 5, 100)
        rows += (
            '<tr>'
            f'<td class="rank-cell">#{rank}</td>'
            f'<td class="team-cell">{team}</td>'
            f'<td><div class="bar-container"><div class="bar" style="width:{bar}%"></div></div></td>'
            f'<td class="prob-val">{pc:.1f}%</td>'
            f'<td class="muted-cell">{pf:.1f}%</td>'
            f'<td class="muted-cell">{p3:.1f}%</td>'
            f'<td class="muted-cell">{p4:.1f}%</td>'
            f'<td class="muted-cell">{ps:.1f}%</td>'
            '</tr>'
        )
    return rows


