DASHBOARD_JS = """function calcGroupProbs(rank1, rank2) {
  const elo1 = 2000 - (rank1-1)*12.2;
  const elo2 = 2000 - (rank2-1)*12.2;
  const diff = elo1 - elo2;
  const exp1 = 1/(1+Math.pow(10,-diff/400));
  const draw = Math.max(0.10, 0.28 - Math.abs(diff)/2000);
  const p1 = exp1*(1-draw);
  const p2 = (1-exp1)*(1-draw);
  const total = p1+draw+p2;
  return [+(p1/total*100).toFixed(1), +(draw/total*100).toFixed(1), +(p2/total*100).toFixed(1)];
}

function calcKoProbs(rank1, rank2) {
  const elo1 = 2000 - (rank1-1)*12.2;
  const elo2 = 2000 - (rank2-1)*12.2;
  const diff = elo1 - elo2;
  const exp1 = 1/(1+Math.pow(10,-diff/400));
  return [+(exp1*100).toFixed(1), +((1-exp1)*100).toFixed(1)];
}

function populateSelects(ids, defaults) {
  const sorted = Object.keys(TEAMS).sort((a,b) => TEAMS[a].rank - TEAMS[b].rank);
  ids.forEach((id, idx) => {
    const sel = document.getElementById(id);
    sorted.forEach(team => {
      const opt = document.createElement('option');
      opt.value = team; opt.textContent = team;
      if (team === defaults[idx]) opt.selected = true;
      sel.appendChild(opt);
    });
  });
}

function updateGroupSim() {
  const t1 = document.getElementById('g-team1').value;
  const t2 = document.getElementById('g-team2').value;
  const d1 = TEAMS[t1], d2 = TEAMS[t2];
  const [p1, pd, p2] = calcGroupProbs(d1.rank, d2.rank);
  document.getElementById('g-bar1').style.width = p1+'%';
  document.getElementById('g-barD').style.width = pd+'%';
  document.getElementById('g-bar2').style.width = p2+'%';
  document.getElementById('g-bar1').textContent = p1+'%';
  document.getElementById('g-barD').textContent = pd+'%';
  document.getElementById('g-bar2').textContent = p2+'%';
  document.getElementById('g-lbl1').textContent = t1+' win';
  document.getElementById('g-lbl2').textContent = t2+' win';
  document.getElementById('g-rank').textContent = '#'+d1.rank+' vs #'+d2.rank;
  document.getElementById('g-probs').textContent = p1+'% / '+pd+'% / '+p2+'%';
  const winner = p1 > p2 ? t1 : (p2 > p1 ? t2 : 'Draw');
  document.getElementById('g-outcome').textContent = winner === 'Draw' ? 'Draw most likely' : winner;
}

function updateKoSim() {
  const t1 = document.getElementById('k-team1').value;
  const t2 = document.getElementById('k-team2').value;
  const d1 = TEAMS[t1], d2 = TEAMS[t2];
  const [p1, p2] = calcKoProbs(d1.rank, d2.rank);
  document.getElementById('k-bar1').style.width = p1+'%';
  document.getElementById('k-bar2').style.width = p2+'%';
  document.getElementById('k-bar1').textContent = p1+'%';
  document.getElementById('k-bar2').textContent = p2+'%';
  document.getElementById('k-lbl1').textContent = t1+' qualifies';
  document.getElementById('k-lbl2').textContent = t2+' qualifies';
  document.getElementById('k-rank').textContent = '#'+d1.rank+' vs #'+d2.rank;
  document.getElementById('k-probs').textContent = p1+'% vs '+p2+'%';
  const winner = p1 >= p2 ? t1 : t2;
  document.getElementById('k-outcome').textContent = winner + ' qualifies';
}

function showTab(tab, evt) {
  document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('panel-'+tab).classList.add('active');
  if (evt && evt.currentTarget) evt.currentTarget.classList.add('active');
}

populateSelects(['g-team1','g-team2'], ['Argentina','Spain']);
populateSelects(['k-team1','k-team2'], ['Argentina','Spain']);
updateGroupSim();
updateKoSim();
"""

